import java.util.*;
import java.io.*;

public class Main {
    static String minCost(long[] weights, long[] costs, long target) {
        // Write your solution here
        // Return "-1", an integer such as "13", or a reduced fraction such as "27/2"
        return "-1";
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long target = (long) in.nval;
        long[] weights = new long[n], costs = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); weights[i] = (long) in.nval;
            in.nextToken(); costs[i] = (long) in.nval;
        }
        System.out.println(minCost(weights, costs, target));
    }
}
